def find_regions(grid):
    regions = []
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] != 0:
                # Start of a region (leftmost in row)
                start_col = c
                end_col = c
                while end_col < len(grid[0]) and grid[r][end_col] != 0:
                    end_col += 1
                regions.append((r, c, start_col, end_col))
    return regions

